layers.vertex:
attribute vec3 aO, aT; attribute float aK; uniform float uTime; varying vec2 vP; varying float vU, vE, vOk, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    void main(){ float u = uTime - aT.x, e = uTime - aT.y; if (u < 0. || e > 1.3){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vE = e; vOk = aT.z; vK = aK;
      vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
      if (aK < .5){ float S = 1.1; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(vP.x, .03, -vP.y), 1.); return; }
      if (aK < 1.5){ vP = vec2(position.x*1.2, (position.y*.5 + .5)*3.);              /* star shower over the body (metres), Y-dominant */
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + f*.15 + rt*vP.x + vec3(0., vP.y, 0.), 1.); return; }
      if (aK > 3.5){ vP = vec2(position.x, position.y*.5 + .5);                        /* resolve: rising light over the body */
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + f*.2 + rt*position.x*.7 + vec3(0., vP.y*2.4, 0.), 1.); return; }
      vec3 C = aO + vec3(0., aK < 2.5 ? 5.400 : .3, 0.); float S = aK < 2.5 ? .8 : .6;
      vec4 mv = viewMatrix*vec4(C, 1.); mv.xyz += normalize(-mv.xyz)*.3; mv.xy += position.xy*S; vP = position.xy; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform float uTime; uniform vec3 uC, uB, uW; varying vec2 vP; varying float vU, vE, vOk, vK; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    void main(){
      float lum = 0., hot = 0., cy = 0.;
      float fin = smoothstep(0., .35, vU), fout = vE > 0. ? 1. - clamp(vE/(vOk > .5 ? .45 : .3), 0., 1.) : 1.;
      if (vK < .5){
        /* small circle around the body: two thin rings + faint ticks, very slow turn; opens a little on the resolve */
        float r = length(vP), a = atan(vP.y, vP.x), R = .85*(vE > 0. && vOk > .5 ? 1. + .25*eox(clamp(vE/.5, 0., 1.)) : mix(.6, 1., eox(clamp(vU/.4, 0., 1.))));
        float tk = smoothstep(.75, .98, abs(cos(a*8. + uTime*.15)))*exp(-pow((r - R*.8)/.025, 2.));
        lum = line(r - R, .012)*.8 + line(r - R*.7, .007)*.4 + tk*.35 + exp(-r*r*3.)*.05;
        hot = line(r - R, .004)*.35; lum *= fin*fout; hot *= fin*fout;
        lum *= smoothstep(1.1, .98, r); hot *= smoothstep(1.1, .98, r);
      } else if (vK < 1.5){
        /* the Astral Step stars fall onto the body, one after another, for the whole cast; each lands with a small glint.
           New stars stop when the cast ends (the last ones still land); interrupted: everything fades */
        float T = .95;
        for (int i=0;i<14;i++){ float fi = float(i), tt = vU + fract(sin(fi*37.3)*431.7)*T, cyc = floor(tt/T), l = fract(tt/T);
          float born = vU - l*T; if (born < 0.) continue;
          if (vE > 0. && vOk > .5 && l*T < vE) continue;                                 /* no new stars after the cast */
          float hs = fract(sin((fi + cyc*7.31)*91.7)*43758.5), hx = fract(sin((fi*3.1 + cyc*1.7)*57.3)*1375.5);
          float x = (hx - .5)*1.9, y0 = 2.4 + .5*hs, yl = .28;
          float k = clamp(l/.75, 0., 1.), y = mix(y0, yl, k*k);
          float sz = .035 + .03*hs, tw = .7 + .3*sin(uTime*24. + fi*2.3);
          vec2 q = vP - vec2(x, y); float qr = length(q), qa = atan(q.y, q.x);
          float st = (pow(abs(cos(qa*2.)), 12.)*exp(-qr/sz*1.4) + exp(-qr*qr/(sz*sz*.08)))*tw*smoothstep(0., .12, l)*(l < .75 ? 1. : 0.);
          float land = l >= .75 ? exp(-(l - .75)*T*9.) : 0.;                              /* glint where it lands on the body */
          vec2 g = vP - vec2(x, yl); float gr = length(g), ga = atan(g.y, g.x);
          st += (pow(abs(cos(ga*2.)), 16.)*exp(-gr*9.) + exp(-gr*gr*900.))*land*.9;
          lum += st; hot += exp(-qr*qr/(sz*sz*.03))*tw*(l < .75 ? 1. : 0.) + exp(-gr*gr*2500.)*land; }
        lum *= fout; hot *= fout;
        lum *= smoothstep(1.2, 1., abs(vP.x))*smoothstep(3., 2.7, vP.y); hot *= smoothstep(1.2, 1., abs(vP.x));
      } else if (vK < 2.5){
        /* the star at the top (icon): 4 long rays + short diagonals + a fine circle */
        float r = length(vP), a = atan(vP.y, vP.x);
        float st = pow(abs(cos(a*2.)), 24.)*exp(-r*2.4) + pow(abs(cos(a*2. + .785)), 50.)*exp(-r*5.)*.4;
        float ring = line(r - .55, .01)*.35, core = exp(-r*r*70.);
        float f = fin*(vE > 0. ? 1. - clamp(vE/.25, 0., 1.) : 1.);
        lum = (st + ring)*f; hot = (core*1.4 + st*.3)*f; lum *= smoothstep(1., .85, r); hot *= smoothstep(1., .85, r);
      } else if (vK < 3.5){
        /* the beam's end on the body: a clear, steady soft glow at the contact point */
        float r = length(vP), f = smoothstep(.3, .45, vU)*fout;
        lum = (exp(-r*r*14.)*.45 + exp(-r*r*120.)*.6)*f; hot = exp(-r*r*400.)*f;
        lum *= smoothstep(1., .85, r);
      } else {
        /* resolve (only if the cast completes): a soft column of light rises gently with the body as it stands - no burst */
        float x = vP.x, h = vP.y, t = vU/1.1, top = eox(clamp(vU/.9, 0., 1.)), f = 1. - smoothstep(.45, 1., t);
        float col = 0.;
        for (int j=0;j<3;j++){ float fj = float(j), cx = (fj - 1.)*.32 + sin(h*8. - vU*3. + fj*2.)*.045;
          float brk = .4 + .6*smoothstep(.2, .8, .5 + .5*sin(h*18. - vU*5. + fj*3.));
          col += exp(-pow((x - cx)/.095, 2.))*brk*.14; }
        col *= smoothstep(top + .02, top - .25, h)*smoothstep(0., .08, h);
        for (int i=0;i<5;i++){ float fi = float(i), sx = (fract(sin(fi*91.7)*437.5) - .5)*1.2, sh = top*(.55 + .08*fi);
          vec2 q = vec2(x - sx, (h - sh)*3.4); float qr = length(q), qa = atan(q.y, q.x);
          lum += (pow(abs(cos(qa*2.)), 14.)*exp(-qr*18.) + exp(-qr*qr*900.))*.6; }
        lum = (lum + col)*f; hot = col*.6*f;
        lum *= smoothstep(1., .8, abs(x)); hot *= smoothstep(1., .8, abs(x));
      }
      vec3 o = uC*lum*.8 + uB*(lum*.35 + cy) + uW*hot*.8;
      o = max(o, 0.); if (!(max(o.r, max(o.g, o.b)) >= .002)) discard; gl_FragColor = vec4(o, 1.); }
